  "implementation": "import math\\ndef solve(case):\\n    vectors = case[\\\"sentence_vectors\\\"]\\n    query = case[\\\"query_vector\\\"]\\n    w = case[\\\"context_weight\\\"]\\n    n = len(vectors)\\n    def cosine_sim(v, q):\\n        dot = sum(a*b for a,b in zip(v,q))\\n        norm_v = math.sqrt(sum(a*a for a in v))\\n        norm_q = math.sqrt(sum(a*a for a in q))\\n        if norm_v == 0 or norm_q == 0:\\n            return 0.0\\n        return dot / (norm_v * norm_q)\\n    sims = [cosine_sim(v, query) for v in vectors]\\n    neigh_avgs = []\\n    for i in range(n):\\n        if n == 1:\\n            neigh_avgs.append(0.0)\\n        else:\\n            left = sims[i-1] if i > 0 else None\\n            right = sims[i+1] if i < n-1 else None\\n            if left is None:\\n                avg = right\\n            elif right is None:\\n                avg = left\\n            else:\\n                avg = (left + right) / 2.0\\n            neigh_avgs.append(avg)\\n    scores = [(1-w)*sims[i] + w*neigh_avgs[i] for i in range(n)]\\n    scores = [round(s, 6) for s in scores]\\n    ranking = sorted(range(n), key=lambda i: (-scores[i], i))\\n    sorted_scores = [scores[i] for i in ranking]\\n    return {\\\"ranking\\\": ranking, \\\"scores\\\": sorted_scores}"
}
